# Validate the PNGs generated by codecs.jsx.
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
$output = Join-Path $root 'target/codec-map-codecs'
Add-Type -AssemblyName System.Drawing
$report = [Collections.Generic.List[string]]::new()
function Compare-Images([string]$Reference, [string]$Result, [string]$Rule) {
    $a = [Drawing.Bitmap]::new((Join-Path $output "$Reference.png"))
    $b = [Drawing.Bitmap]::new((Join-Path $output "$Result.png"))
    try {
        if ($a.Width -ne $b.Width -or $a.Height -ne $b.Height) { throw "Size mismatch: $Result" }
        $different = 0
        for ($y = 0; $y -lt $a.Height; $y++) {
            for ($x = 0; $x -lt $a.Width; $x++) {
                $p = $a.GetPixel($x, $y); $q = $b.GetPixel($x, $y)
                if ($Rule -eq 'hold-opaque' -and ($p.A -ne 255 -or $q.A -ne 255)) { continue }
                if ($p.A -ne $q.A) { throw "Alpha changed: $Result at $x,$y" }
                if ($p.ToArgb() -ne $q.ToArgb()) {
                    $different++
                    if ($Rule -eq 'equal' -or $Rule -eq 'hold-opaque' -or ($Rule -eq 'left-exact' -and $x -lt 64)) {
                        throw "Pixel changed unexpectedly: $Result at $x,$y"
                    }
                }
            }
        }
        if ($Rule -in @('different', 'left-exact') -and $different -eq 0) { throw "Expected difference: $Result" }
        $report.Add("PASS $Reference -> $Result ($Rule): $different changed pixels")
    } finally { $a.Dispose(); $b.Dispose() }
}
if ((Get-ChildItem -LiteralPath $output -Filter '*.png').Count -ne 40) { throw 'Expected 40 rendered PNGs' }
foreach ($codec in 1..3) {
    Compare-Images "codec$codec-normal" "codec$codec-drop-i" 'different'
    Compare-Images "codec$codec-drop-i" "codec$codec-replay-i" 'equal'
    Compare-Images "codec$codec-normal13" "codec$codec-reset-i" 'equal'
    Compare-Images "codec$codec-seed" "codec$codec-all-i-drop" 'hold-opaque'
    Compare-Images "codec$codec-reference" "codec$codec-isolated" 'left-exact'
    if ($codec -ne 2) {
        Compare-Images "codec$codec-b-normal" "codec$codec-b-drop" 'different'
        Compare-Images "codec$codec-b-drop" "codec$codec-b-replay" 'equal'
        Compare-Images "codec$codec-b-normal3" "codec$codec-b-reset" 'equal'
    }
}
$report | Set-Content -LiteralPath (Join-Path $output 'pixel-report.txt') -Encoding utf8
$report
